/* Refresh the exchange rates in the background (the page works with the rates it was built with, this makes them live). */
(function () {
  try {
    if (!window.fetch) return;
    var K = 'cw_rates_live';
    function apply(j) {
      var C = window.CW_CONFIG;
      if (!j || !j.rates || !C) return false;
      if (Object.keys(j.rates).length < 20) return false;
      C.rates = { base: j.base || 'USD', rates: j.rates, time: j.time || (C.rates && C.rates.time) || 0 };
      if (j.crypto && j.crypto.bitcoin) C.crypto = j.crypto;
      return true;
    }
    var cached = null;
    try { cached = JSON.parse(sessionStorage.getItem(K) || 'null'); } catch (e) {}
    if (cached && Date.now() - cached.t < 1800000 && apply(cached.d)) return;
    fetch('/api/rates').then(function (r) { return r.ok ? r.json() : null; }).then(function (j) {
      if (!apply(j)) return;
      try { sessionStorage.setItem(K, JSON.stringify({ t: Date.now(), d: j })); } catch (e) {}
      // recalculate what is already on screen with the fresh rates
      document.addEventListener('DOMContentLoaded', again);
      if (document.readyState !== 'loading') again();
      function again() {
        setTimeout(function () {
          var i = document.querySelector('.cw-calc input, .cw-calc select');
          if (i) i.dispatchEvent(new Event('input', { bubbles: true }));
        }, 50);
      }
    }).catch(function () {});
  } catch (e) {}
})();
